        if (this.parsingDeclareFile || svAmbient || TypeScript_hasFlag(modifiers, TypeScript_Modifiers.Ambient)) {
            this.ambientModule = true;
        }
        this.currentToken = present(this.scanner).scan();
        var name: TypeScript_AST | null = null;
        var enclosedList: TypeScript_AST[] | null = null;
        this.pushDeclLists();
        var minChar = present(this.scanner).startPos;
        var isDynamicMod = false;
