        moduleBody.limChar = present(this.scanner).pos;
        var endingToken = new TypeScript_ASTSpan();
        endingToken.minChar = present(this.scanner).startPos;
        endingToken.limChar = present(this.scanner).pos;
        this.checkCurrentToken(TypeScript_TokenID.CloseBrace, errorRecoverySet);
        var limChar = present(this.scanner).lastTokenLimChar();
