            var len = enclosedList.length;
            var innerName = classValue(enclosedList[len - 1], TypeScript_Identifier);
            var innerDecl = new TypeScript_ModuleDeclaration(innerName, moduleBody, this.topVarList(), this.topScopeList(), endingToken);
