        var members = new TypeScript_ASTList();
        members.minChar = minChar;
        var prevInInterfaceDecl = this.inInterfaceDecl;
        this.inInterfaceDecl = true;
        this.parseTypeMemberList(errorRecoverySet | TypeScript_ErrorRecoverySet.RCurly, members);
        this.inInterfaceDecl = prevInInterfaceDecl;
        this.checkCurrentToken(TypeScript_TokenID.CloseBrace, errorRecoverySet);
