        var interfaceDecl = new TypeScript_InterfaceDeclaration(this.anonId, members, /*extends:*/ null, /*implementsL*/ null);
        interfaceDecl.minChar = minChar;
        interfaceDecl.limChar = members.limChar; // "}"
