        present(param.id).minChar = present(this.scanner).startPos;
        present(param.id).limChar = present(this.scanner).pos;
        param.minChar = present(param.id).minChar;
        param.limChar = present(param.id).limChar;
        this.currentToken = present(this.scanner).scan();
        var statementPos = present(this.scanner).pos;
        this.checkCurrentToken(TypeScript_TokenID.CloseParen, errorRecoverySet | TypeScript_ErrorRecoverySet.StmtStart);
