                ecatch.statement.minChar = catchMinChar;
                ecatch.statement.limChar = statementPos;
                ecatch.minChar = present(this.scanner).startPos;
                ecatch.limChar = present(this.scanner).pos;
                ecatch.flags |= TypeScript_ASTFlags.Error;
