            parameterTable = new TypeScript_ScopedMembers(new TypeScript_DualStringHashTable(new TypeScript_StringHashTable(), new TypeScript_StringHashTable()));
            parameterBuilder = new TypeScript_SymbolScopeBuilder(parameterTable, null, null, null, null, container);
