        var isExported = TypeScript_hasFlag(present(funcDecl).fncFlags, TypeScript_FncFlags.Exported | TypeScript_FncFlags.ClassPropertyMethodExported) || container == this.gloMod;
        var isStatic = TypeScript_hasFlag(present(funcDecl).fncFlags, TypeScript_FncFlags.Static);
